import { ClientKafka } from '@nestjs/microservices';
import { AgentService } from '../../agent/agent.service';

/**
 * @interface AIQuestion
 * @description Defines the structured format for a critical question generated by the AI.
 * This type ensures consistency between the AI's output and what the workflow expects.
 * It's a shared contract within the `ai-agent-service` domain.
 * @property {string} id - A unique identifier for the question.
 * @property {string} question - The text of the question.
 * @property {'Market' | 'Finance' | 'Operations'} category - The category of the question.
 */
export interface AIQuestion {
  id: string;
  question: string;
  category: 'Market' | 'Finance' | 'Operations';
}

// --- Activity Input/Output Interfaces for clarity and type safety ---

/**
 * @interface NotifyAnalysisCompleteInput
 * @description Input for the `notifyAnalysisCompleted` activity, containing the successful analysis results.
 * @property {string} userId - The ID of the user whose plan was analyzed.
 * @property {string} feedback - The AI-generated feedback.
 * @property {AIQuestion[]} questions - The array of AI-generated questions.
 */
export interface NotifyAnalysisCompleteInput {
  userId: string;
  feedback: string;
  questions: AIQuestion[];
}

/**
 * @interface NotifyAnalysisFailedInput
 * @description Input for the `notifyAnalysisFailed` activity, containing details about the failure.
 * @property {string} userId - The ID of the user whose plan was being analyzed.
 * @property {string} businessPlan - The original business plan, for context.
 * @property {string} error - A description of the error that occurred.
 */
export interface NotifyAnalysisFailedInput {
  userId: string;
  businessPlan: string;
  error: string;
}

/**
 * Creates an object containing the Temporal Activities for the Quantum Weaver workflow.
 * This factory function allows for dependency injection of NestJS services (like AgentService
 * and the Kafka client) into the activities, decoupling the activity logic from service instantiation.
 * The Temporal Worker is responsible for creating service instances and passing them to this factory.
 *
 * @param {AgentService} agentService - An instance of the AgentService to interact with the underlying AI models.
 * @param {ClientKafka} kafkaClient - An instance of the NestJS ClientKafka to emit events to the message bus.
 * @returns {object} An object where keys are activity names and values are the corresponding activity functions.
 */
export function createQuantumWeaverActivities(
  agentService: AgentService,
  kafkaClient: ClientKafka,
) {
  return {
    /**
     * @activity generateFeedback
     * @description Generates high-level feedback for a given business plan using an AI model.
     * This is a distinct, retryable step in the workflow.
     * @param {string} businessPlan - The business plan text to be analyzed.
     * @returns {Promise<string>} A promise that resolves to the generated feedback text.
     */
    async generateFeedback(businessPlan: string): Promise<string> {
      const feedbackPrompt = `Provide concise, high-level feedback on the following business plan: "${businessPlan}"`;
      const feedback = await agentService.generateText({ prompt: feedbackPrompt });
      return feedback;
    },

    /**
     * @activity generateQuestions
     * @description Generates critical questions a venture capitalist might ask about a business plan.
     * The AI is prompted to return a structured JSON response. This activity includes logic
     * to parse and validate the AI's output.
     * @param {string} businessPlan - The business plan text to be analyzed.
     * @returns {Promise<AIQuestion[]>} A promise that resolves to an array of structured questions.
     * @throws {Error} Throws an application error if the AI's JSON response is malformed, allowing Temporal to handle the failure.
     */
    async generateQuestions(businessPlan: string): Promise<AIQuestion[]> {
      const questionsPrompt = `Based on the business plan provided, generate 3 critical questions a Venture Capitalist might ask. Categorize each question into 'Market', 'Finance', or 'Operations'. Your response must be a valid JSON array of objects, where each object has "id", "question", and "category" keys. Business Plan: "${businessPlan}"`;

      const questionsText = await agentService.generateText({ prompt: questionsPrompt });

      // Clean up potential markdown formatting from the AI response before parsing.
      const cleanedJson = questionsText.replace(/```json|```/g, '').trim();

      try {
        const questions: AIQuestion[] = JSON.parse(cleanedJson);
        // Basic validation to ensure the AI returned the expected structure
        if (!Array.isArray(questions) || questions.some(q => !q.id || !q.question || !q.category)) {
          throw new Error('AI response is not a valid array of AIQuestion objects.');
        }
        return questions;
      } catch (error) {
        console.error('Failed to parse JSON response from AI for business plan questions.', {
            rawResponse: questionsText,
            cleanedResponse: cleanedJson,
            error: (error as Error).message,
        });
        // Throwing an error here will cause the activity to fail, triggering Temporal's retry policy.
        throw new Error('AI returned a malformed JSON response for questions.');
      }
    },

    /**
     * @activity notifyAnalysisCompleted
     * @description Notifies the rest of the system that the business plan analysis has completed successfully.
     * It emits an event to a Kafka topic, which can be consumed by other services (e.g., to update a database or send a user notification).
     * This is a "fire-and-forget" activity.
     * @param {NotifyAnalysisCompleteInput} input - Contains the userId and the results of the analysis.
     * @returns {Promise<void>} A promise that resolves when the event has been emitted.
     */
    async notifyAnalysisCompleted(input: NotifyAnalysisCompleteInput): Promise<void> {
      const { userId, feedback, questions } = input;

      kafkaClient.emit('agent.business_plan_analysis.completed', {
        userId,
        feedback,
        questions,
        status: 'success',
        timestamp: new Date().toISOString(),
      });
      // The `emit` method is fire-and-forget. We'll resolve the promise to signal completion to the workflow.
      return Promise.resolve();
    },

    /**
     * @activity notifyAnalysisFailed
     * @description Notifies the rest of the system that the business plan analysis has failed.
     * This is part of the saga's compensation/failure path. It emits an event to a Kafka topic
     * so that other services can react to the failure.
     * @param {NotifyAnalysisFailedInput} input - Contains details about the failure.
     * @returns {Promise<void>} A promise that resolves when the event has been emitted.
     */
    async notifyAnalysisFailed(input: NotifyAnalysisFailedInput): Promise<void> {
      const { userId, businessPlan, error } = input;

      kafkaClient.emit('agent.business_plan_analysis.failed', {
        userId,
        businessPlan, // Include original plan for context/retry purposes
        error,
        status: 'failed',
        timestamp: new Date().toISOString(),
      });
      return Promise.resolve();
    },
  };
}
